package net.civeira.phylax.feature.template.templateversion.domain.valueholder;

import java.util.Optional;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

import net.civeira.phylax.common.value.validation.ConstraintFailList;
import net.civeira.phylax.feature.template.templateversion.domain.TemplateVersion;
import net.civeira.phylax.feature.template.templateversion.domain.valueobject.VersionVO;

class VersionValueHolderUnitTest {

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign plain values on the holder of version of template version")
  void test_version_value_holder_assign_plain_value() {
    Object holder = new Object();
    VersionValueHolder<Object> value = new VersionValueHolder<>(holder);
    Assertions.assertSame(holder, value.version(1), "Setters must return the holder");
    Assertions.assertTrue(value.getVersionValue().isPresent(), "The plain value must be stored");
    Assertions.assertEquals(1, value.getVersion().orElse(null),
        "The plain value must be recovered");
    Assertions.assertSame(holder, value.versionNull(), "Setters must return the holder");
    Assertions.assertTrue(value.getVersionValue().isPresent(),
        "A null value object must be stored");
    Assertions.assertFalse(value.getVersion().isPresent(), "A null value must not have content");
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign value objects on the holder of version of template version")
  void test_version_value_holder_assign_value_object() {
    Object holder = new Object();
    VersionValueHolder<Object> value = new VersionValueHolder<>(holder);
    VersionVO vo = VersionVO.from(1);
    Assertions.assertFalse(value.getVersionValue().isPresent(), "A new holder must be empty");
    Assertions.assertSame(holder, value.version(vo), "Setters must return the holder");
    Assertions.assertSame(vo, value.getVersionValue().orElseThrow());
    Assertions.assertSame(holder, value.version(Optional.empty()));
    Assertions.assertFalse(value.getVersionValue().isPresent(),
        "An empty optional must clear the value");
    Assertions.assertSame(holder, value.version(Optional.of(vo)));
    Assertions.assertSame(vo, value.getVersionValue().orElseThrow());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test read the value of the holder of version of template version against the original")
  void test_version_value_holder_read() {
    Object holder = new Object();
    VersionValueHolder<Object> value = new VersionValueHolder<>(holder);
    VersionVO vo = VersionVO.from(1);
    VersionVO other = VersionVO.from(1);
    TemplateVersion original = Mockito.mock(TemplateVersion.class);
    Mockito.when(original.getVersionValue()).thenReturn(other);
    ConstraintFailList fails = new ConstraintFailList();
    Assertions.assertSame(other, value.readVersion(Optional.of(original), fails),
        "Without value, the original must be used");
    Assertions.assertTrue(fails.isEmpty());
    Assertions.assertNotNull(value.readVersion(Optional.empty(), fails),
        "Without value and original a null value is returned");
    Assertions.assertTrue(fails.isEmpty(), "An optional value is never reported as missing");
    value.version(vo);
    ConstraintFailList others = new ConstraintFailList();
    Assertions.assertSame(vo, value.readVersion(Optional.of(original), others),
        "With value, the original is ignored");
    Assertions.assertSame(vo, value.readVersion(Optional.empty(), others));
    Assertions.assertTrue(others.isEmpty());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test unset the value of the holder of version of template version")
  void test_version_value_holder_unset() {
    Object holder = new Object();
    VersionValueHolder<Object> value = new VersionValueHolder<>(holder);
    VersionVO vo = VersionVO.from(1);
    value.version(vo);
    Assertions.assertSame(holder, value.unsetVersionIfMatches("version_other"));
    Assertions.assertTrue(value.getVersionValue().isPresent(),
        "Other field name must keep the value");
    Assertions.assertSame(holder, value.unsetVersionIfMatches("version"));
    Assertions.assertFalse(value.getVersionValue().isPresent(),
        "The field name must clear the value");
    value.version(vo);
    Assertions.assertSame(holder, value.unsetVersion());
    Assertions.assertFalse(value.getVersionValue().isPresent(), "Unset must clear the value");
  }
}
